#include "content/MachineRecipeGate.hpp"
namespace elysium::content {bool MachineRecipeGate::addKnownMachine(ContentId id){if(!id)return false;machines_[id]=true;return true;}bool MachineRecipeGate::addRow(MachineRecipeRow r){if(!r.machine||!r.constructionRecipe||rows_.contains(r.machine))return false;rows_[r.machine]=r;return true;}const MachineRecipeRow*MachineRecipeGate::find(ContentId id)const{auto i=rows_.find(id);return i==rows_.end()?nullptr:&i->second;}std::vector<GateIssue>MachineRecipeGate::validate()const{std::vector<GateIssue>o;for(auto&[id,r]:rows_){if(!machines_.contains(id))o.push_back({id,"unknown_machine"});if(!r.station)o.push_back({id,"missing_station"});if(r.status==IntegrationStatus::Current&&(r.evidence&requiredEvidence)!=requiredEvidence)o.push_back({id,"current_without_required_evidence"});}return o;}bool MachineRecipeGate::promote(ContentId id){auto i=rows_.find(id);if(i==rows_.end()||!machines_.contains(id)||(i->second.evidence&requiredEvidence)!=requiredEvidence)return false;i->second.status=IntegrationStatus::Current;return true;}}
